<?php
declare(strict_types=1);
require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('payment_methods.send');
$id=(int)($_GET['id']??$_POST['id']??0);$stmt=db()->prepare('SELECT * FROM payment_methods WHERE id=?');$stmt->execute([$id]);$method=$stmt->fetch();if(!$method){http_response_code(404);exit('Forma de pago no encontrada.');}$pageTitle='Enviar forma de pago';$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$channel=(string)($_POST['channel']??'email');$recipient=trim((string)($_POST['recipient']??''));$message=trim((string)($_POST['message']??''));$intro=$message!==''?$message:'Compartimos los datos de pago solicitados.';$body=$method['name']."\n".($method['country']?'País: '.$method['country']."\n":'').'Moneda: '.$method['currency']."\n\n".$method['details'];
    if($channel==='email'){
        if(!filter_var($recipient,FILTER_VALIDATE_EMAIL))$errors[]='El email no es válido.';
        if(!$errors){$html='<!doctype html><html><body style="margin:0;padding:24px;background:#edf3f7;font-family:Arial,sans-serif;color:#183247"><div style="max-width:650px;margin:auto;background:#fff;border:1px solid #d8e3ea;border-radius:18px;overflow:hidden"><div style="height:7px;background:#ff5300"></div><div style="padding:28px"><h2 style="margin-top:0;color:#002f57">'.e($method['name']).'</h2><p style="line-height:1.6">'.nl2br(e($intro)).'</p><div style="background:#f7fafc;border:1px solid #d8e3ea;border-left:5px solid #ff5300;border-radius:12px;padding:17px;white-space:pre-wrap;line-height:1.6">'.e($body).'</div><p style="font-size:12px;color:#657b8c">SÓCRATES ONE · Creative Studio</p></div></div></body></html>';$result=send_system_email($recipient,'Datos de pago · '.$method['name'],$html);if($result['success']){flash('success','Forma de pago enviada por email.');redirect('payment_methods.php');}$errors[]='No se pudo enviar: '.$result['error'];}
    }elseif($channel==='whatsapp'){
        if(preg_replace('/\D+/','',$recipient)==='')$errors[]='Indica el WhatsApp con código de país.';
        if(!$errors){$result=send_whatsapp_cloud_message($recipient,$intro."\n\n".$body);if($result['success']){flash('success','Forma de pago enviada por WhatsApp.');redirect('payment_methods.php');}$errors[]='No se pudo enviar por WhatsApp: '.$result['error'];}
    }else{$errors[]='Canal no válido.';}
}
require __DIR__.'/includes/header.php';?>
<?php foreach($errors as$error):?><div class="alert alert-error"><?=e($error)?></div><?php endforeach;?><div class="dashboard-grid"><form method="post" class="panel"><div class="panel-header"><div><h2>Enviar datos de pago</h2><span class="table-sub">Puedes enviarlos por email o por WhatsApp Cloud API.</span></div></div><div class="panel-body form-grid"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><label>Canal<select name="channel" data-payment-channel><option value="email" <?=($_POST['channel']??'email')==='email'?'selected':''?>>Email</option><option value="whatsapp" <?=($_POST['channel']??'')==='whatsapp'?'selected':''?>>WhatsApp</option></select></label><label>Destinatario *<input name="recipient" required value="<?=e($_POST['recipient']??'')?>" placeholder="email@cliente.com o +56 9..."></label><label class="full">Mensaje introductorio<textarea name="message" placeholder="Compartimos los datos de pago solicitados."><?=e($_POST['message']??'')?></textarea></label><div class="full form-actions"><a class="btn btn-light" href="payment_methods.php">Cancelar</a><button class="btn btn-primary">ENVIAR</button></div></div></form><aside class="panel"><div class="panel-header"><h2>Vista previa</h2></div><div class="panel-body"><strong><?=e($method['name'])?></strong><pre class="payment-method-preview" style="margin-top:12px"><?=e($method['details'])?></pre></div></aside></div><?php require __DIR__.'/includes/footer.php';?>
